// RELATED: beacon_chain/spec/state_transition_block.nim:process_deposit_request (lines 372-391)
// nimbus-eth2 processes each DepositRequest by appending to pending_deposits
func process_deposit_request*(...) =
  if state.pending_deposits.add(PendingDeposit(
      pubkey: deposit_request.pubkey,
      withdrawal_credentials: deposit_request.withdrawal_credentials,
      amount: deposit_request.amount,
      signature: deposit_request.signature,
      slot: state.slot)):
    ok()
  else:
    err("process_deposit_request: couldn't add deposit to pending_deposits")

