// PRIMARY: beacon_chain/spec/helpers.nim:computeRequestsHash (lines 451-472)
// Order dependency enforced by sequential SHA-256 updates (SHA-256 is not commutative)
func computeRequestsHash(requests: electra.ExecutionRequests): EthHash32 =
  template individualHash(requestType, requestList): Digest =
    computeDigest:
      h.update([requestType.byte])
      for request in requestList:  // order-dependent iteration
        h.update SSZ.encode(request)
  let requestsHash = computeDigest:
    // fixed order: DEPOSIT_REQUEST_TYPE < WITHDRAWAL_REQUEST_TYPE < CONSOLIDATION_REQUEST_TYPE
    mixInRequests(DEPOSIT_REQUEST_TYPE, requests.deposits)
    mixInRequests(WITHDRAWAL_REQUEST_TYPE, requests.withdrawals)
    mixInRequests(CONSOLIDATION_REQUEST_TYPE, requests.consolidations)
  requestsHash.to(EthHash32)

// PRIMARY: beacon_chain/spec/helpers.nim:computeRequestsHash (lines 451-472)
// Empty requests: mixInRequests only updates if requestList.len > 0
// So if all lists are empty, requestsHash = SHA-256('') = SHA-256 of empty string
func computeRequestsHash(requests: electra.ExecutionRequests): EthHash32 =
  let requestsHash = computeDigest:
    template mixInRequests(requestType, requestList): untyped =
      if requestList.len > 0:   // <-- skip if empty list
        h.update(individualHash(requestType, requestList).data)
    mixInRequests(DEPOSIT_REQUEST_TYPE, requests.deposits)
    mixInRequests(WITHDRAWAL_REQUEST_TYPE, requests.withdrawals)
    mixInRequests(CONSOLIDATION_REQUEST_TYPE, requests.consolidations)
  requestsHash.to(EthHash32)

